unitsize(0.6 cm);

real upperparab (real x) {
  return (sqrt(4*x));
}

real lowerparab (real x) {
  return (-sqrt(4*x));
}

pair A, B, P, Q, R;

A = (1,0);
B = (5,4);
P = (1.5,upperparab(1.5));
Q = (-1,upperparab(1.5));
R = (-1,4);

draw(A--P--B);
draw(graph(upperparab,0,6));
